import{c as p,Z as r,Q as d,j as e,m as a,o,av as i,n as l,g as s}from"./chunks/framework.rWdQudnF.js";const v=JSON.parse('{"title":"进程管理","description":"","frontmatter":{"title":"进程管理"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/进程管理.md","filePath":"综合知识/系统基础/操作系统/进程管理.md","lastUpdated":null}'),c={name:"综合知识/系统基础/操作系统/进程管理.md"},u={class:"callout callout-note"},g={class:"callout-body"};function h(b,t,m,P,y,S){const n=r("font");return d(),e("div",null,[t[8]||(t[8]=a(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 进程组成与 PCB 组织方式</li><li>[x] 三态模型与状态转换</li><li>[x] 进程同步与互斥（临界资源/临界区）</li><li>[x] 信号量与 PV 操作</li><li>[x] 信号量值含义与前趋图 PV 规则</li><li>[x] 生产者-消费者问题</li><li>[x] 三级调度与调度算法</li><li>[x] 死锁（必要条件/处理策略/资源计算公式）</li><li>[x] 线程 vs 进程</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="进程组成与-pcb-组织方式" tabindex="-1">进程组成与 PCB 组织方式 <a class="header-anchor" href="#进程组成与-pcb-组织方式" aria-label="Permalink to &quot;进程组成与 PCB 组织方式&quot;">​</a></h3><blockquote><p>🎯 一句话结论：进程由 <strong>PCB + 程序 + 数据</strong> 三部分组成，是<strong>系统资源分配和调度的基本单位</strong>。</p></blockquote><p><strong>进程组成</strong>：PCB（进程控制块，唯一标识）、程序（描述做什么）、数据（执行所需数据）。</p><p><strong>PCB 组织方式</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th></tr></thead><tbody><tr><td>链接方式</td><td>PCB 通过链表链接，同一状态的 PCB 链接成一个队列</td></tr><tr><td>索引方式</td><td>同状态的 PCB 集中记录在索引表中，通过索引表查找</td></tr><tr><td>顺序方式</td><td>PCB 按顺序连续存放（不适用于动态变化）</td></tr></tbody></table><blockquote><p>⚠️ 三种方式中<strong>索引方式</strong>最常见：为每种进程状态建立索引表，PCB 记录在索引表中。</p></blockquote><h3 id="三态模型" tabindex="-1">三态模型 <a class="header-anchor" href="#三态模型" aria-label="Permalink to &quot;三态模型&quot;">​</a></h3><p><strong>三态模型</strong>（必须熟练掌握转换）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行 → 就绪（时间片到）</span></span>
<span class="line"><span>运行 → 阻塞（等待某事件）</span></span>
<span class="line"><span>阻塞 → 就绪（等待的事件发生）</span></span>
<span class="line"><span>就绪 → 运行（被调度）</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/fc91e36be89335389d25459e5b84134b_MD5.png" alt="进程三态图"></p><ul><li><p>三态模型包括：就绪、运行、阻塞。</p></li><li><p><strong>五态模型有两种版本</strong>，考场上以题目选项为准：</p><table tabindex="0"><thead><tr><th>版本</th><th>包含状态</th><th>来源</th></tr></thead><tbody><tr><td><strong>软考版</strong></td><td>三态 + <strong>挂起</strong> + <strong>终止</strong></td><td>软考部分真题采用此说法</td></tr><tr><td><strong>标准教材版</strong></td><td>三态 + <strong>新建(New)</strong> + <strong>终止(Exit)</strong></td><td>王道/汤小丹等教材，对应七态再加挂起</td></tr></tbody></table><blockquote><p>⚠️ <strong>考场策略</strong>：如果选项同时出现&quot;新建&quot;和&quot;挂起&quot;，选含&quot;新建&quot;的为五态；如果只有&quot;挂起&quot;没有&quot;新建&quot;，则五态选&quot;挂起&quot;。<strong>新建态</strong>在实际 OS 中确实存在，但软考部分题目将其归为创建过程而非独立状态。</p></blockquote></li><li><p>进程基本状态<strong>不包括挂起态</strong>（挂起态是七态模型中的扩展状态）。</p></li><li><p><strong>七态模型</strong> = 五态（标准教材版） + <strong>就绪挂起</strong> + <strong>阻塞挂起</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新建 → 就绪 ↔ 运行 → 终止</span></span>
<span class="line"><span>          ↕        ↕</span></span>
<span class="line"><span>       就绪挂起  阻塞挂起 ← 阻塞</span></span></code></pre></div><blockquote><p>挂起(Suspend)指进程被从内存换出到外存，释放内存空间。就绪挂起（就绪但换出）、阻塞挂起（阻塞且换出），当事件发生或被激活时回到就绪态。</p></blockquote></li></ul><h3 id="前趋图" tabindex="-1">前趋图 <a class="header-anchor" href="#前趋图" aria-label="Permalink to &quot;前趋图&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/前趋图与资源图.html">架构师-备考 综合知识-系统基础-操作系统-前趋图与资源图</a></p><h3 id="进程同步与互斥" tabindex="-1">进程同步与互斥 <a class="header-anchor" href="#进程同步与互斥" aria-label="Permalink to &quot;进程同步与互斥&quot;">​</a></h3><ul><li><strong>临界资源</strong>：各进程间需要以互斥方式对其进行访问的资源</li><li><strong>临界区</strong>：进程中<strong>对临界资源实施操作的那段程序</strong></li><li><strong>互斥</strong>：同一时间只能由一个任务单独使用临界资源，使用时加锁（如多进程共享打印机）</li><li><strong>同步</strong>：多个任务可并发执行，有速度差异，需要等待协调。目标是确保进程间正确协作。</li></ul><h3 id="信号量与-pv-操作" tabindex="-1">信号量与 PV 操作 <a class="header-anchor" href="#信号量与-pv-操作" aria-label="Permalink to &quot;信号量与 PV 操作&quot;">​</a></h3><blockquote><p>🎯 一句话结论：互斥信号量初值 = 1；同步信号量初值 = 共享资源数量。P 减一申请，V 加一释放。</p></blockquote><p><strong>信号量</strong>：</p><ul><li>互斥信号量：对临界资源互斥访问，<strong>初值为 1</strong></li><li>同步信号量：对共享资源的访问控制，<strong>初值一般是共享资源的数量</strong></li></ul><p><strong>P/V 操作</strong>：</p><ul><li><strong>P 操作（申请资源）</strong>：S = S - 1，若 S ≥ 0 则继续执行；若 S &lt; 0 则阻塞，插入阻塞队列</li><li><strong>V 操作（释放资源）</strong>：S = S + 1，若 S &gt; 0 则继续执行；若 S ≤ 0 则从阻塞队列唤醒一个进程</li></ul><h4 id="信号量值含义与前趋图-pv-规则" tabindex="-1">信号量值含义与前趋图 PV 规则 <a class="header-anchor" href="#信号量值含义与前趋图-pv-规则" aria-label="Permalink to &quot;信号量值含义与前趋图 PV 规则&quot;">​</a></h4>`,25)),o(n,{color:"#f79646"},{default:i(()=>[...t[0]||(t[0]=[l("信号量，分为互斥信号量和同步信号量。",-1)])]),_:1}),t[9]||(t[9]=a(`<p>前驱图 PV 规则，是同步信号量下的行为。</p><blockquote><p>🎯 一句话结论：S &lt; 0 时，|S| = 等待进程数。前趋图中信号量数 = 有向边数，初值全 0。</p></blockquote><p><strong>信号量值含义</strong>：</p><ul><li>S ≥ 0：信号量的值表示<strong>可用的资源数</strong></li><li>S &lt; 0：信号量的绝对值 = <strong>等待该资源的进程数</strong></li><li>例：S 初值为 3，当前值为 -1 → 有 <strong>1</strong> 个进程在等待</li></ul><p><strong>前趋图 PV 操作规则</strong>：</p><ul><li>信号量数量 = 前趋图中的<strong>有向边数量</strong></li><li>所有信号量<strong>初值均为 0</strong></li><li>前驱进程完成后执行 <strong>V 操作</strong>（发出信号）</li><li>后继进程开始前执行 <strong>P 操作</strong>（等待信号）</li></ul><p>💡 <strong>核心理解：信号量 = 一条私有消息通道</strong></p><p><strong>关键洞察：每个信号量本质上就是一个独立的消息通道（定向通知），每条有向边配备一个专属信号量，仅供该边对应的后继进程消费。</strong></p><h4 id="为什么互斥信号量只需要一个" tabindex="-1">为什么互斥信号量只需要一个？ <a class="header-anchor" href="#为什么互斥信号量只需要一个" aria-label="Permalink to &quot;为什么互斥信号量只需要一个？&quot;">​</a></h4><p>互斥信号量保护的是<strong>共享资源</strong>，不管谁来用，大家争<strong>同一个锁</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    你 ──→ [打印机] ←── 室友</span></span>
<span class="line"><span>          锁 (S=1)</span></span></code></pre></div><p>所有人对同一个信号量做 P/V，因为争的是同一把锁。<strong>一个锁就够了。</strong></p><h4 id="为什么同步信号量需要-有向边数" tabindex="-1">为什么同步信号量需要 = 有向边数？ <a class="header-anchor" href="#为什么同步信号量需要-有向边数" aria-label="Permalink to &quot;为什么同步信号量需要 = 有向边数？&quot;">​</a></h4><p>同步信号量传递的是<strong>定向通知</strong> — 前驱要明确告诉&quot;某个特定的后继&quot;可以开始了。每条边是一个独立的依赖关系，每个依赖需要一个专属的信号量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            ┌─ S12 ──→ P2</span></span>
<span class="line"><span>    P1 ────┤</span></span>
<span class="line"><span>            └─ S13 ──→ P3</span></span></code></pre></div><p>如果 P1→P2 和 P1→P3 共用同一个信号量 S：</p><ul><li>P1 做完 V(S) 一次，S=1</li><li>P2 和 P3 谁先跑 P(S) 谁抢到，<strong>不能保证发给正确的人</strong></li><li>⚠️ <strong>V 操作不知道要唤醒谁，它只是唤醒一个排队的人</strong></li></ul><p>用两个信号量 S12 和 S13，各管各的通道：</p><ul><li>P1 V(S12) → 只通知 P2</li><li>P1 V(S13) → 只通知 P3</li><li>P2 只能 P(S12)，P3 只能 P(S13)，<strong>各收各的信号，永不串线</strong></li></ul><h4 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h4><table tabindex="0"><thead><tr><th></th><th>互斥信号量</th><th>同步信号量</th></tr></thead><tbody><tr><td>模型</td><td>一把锁，大家争</td><td>多条通道，各收各的信</td></tr><tr><td>数量</td><td>1（保护一个资源）</td><td>= 有向边数（每条边一个通道）</td></tr><tr><td>初值</td><td>1（没人锁）</td><td>0（信号还没发出）</td></tr><tr><td>操作者</td><td>同进程内 P→V</td><td>前驱 V，后继 P，跨两个进程</td></tr></tbody></table><h3 id="生产者-消费者问题" tabindex="-1">生产者-消费者问题 <a class="header-anchor" href="#生产者-消费者问题" aria-label="Permalink to &quot;生产者-消费者问题&quot;">​</a></h3><blockquote><p>🎯 一句话结论：三个信号量 — 互斥 S0 + 同步 S1（空闲位）+ 同步 S2（商品数）。</p></blockquote><p><strong>生产者-消费者问题</strong>：三个信号量 — 互斥信号量 S0（仓库使用权，初值 1），同步信号量 S1（空闲位置数），同步信号量 S2（商品个数）。</p><ul><li>⚠️ 不能同时操作缓冲区（即不要求同时操作），但一次只有一个进程操作缓冲区</li><li>⚠️ 不能向满缓冲区存产品，不能从空缓冲区取产品</li></ul><h3 id="进程调度" tabindex="-1">进程调度 <a class="header-anchor" href="#进程调度" aria-label="Permalink to &quot;进程调度&quot;">​</a></h3><p><strong>三级调度</strong>：</p><ul><li>高级调度（作业调度）：决定哪个后备作业调入系统，成为就绪进程。⚠️ <strong>不存在于分时和实时操作系统</strong></li><li>中级调度（对换调度）：决定交换区中哪个就绪进程调入内存</li><li>低级调度（进程调度）：决定内存中哪个就绪进程占用 CPU，最活跃、影响最大。⚠️ <strong>不涉及进程在内存与外存之间交换</strong></li></ul><p><strong>调度算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>特点</th></tr></thead><tbody><tr><td>先来先服务 FCFS</td><td>先到达先分配 CPU，用于宏观调度</td></tr><tr><td>时间片轮转</td><td>每个进程分配相同时间片轮流使用 CPU，用于微观调度</td></tr><tr><td>优先级调度</td><td>优先级大的先分配 CPU</td></tr><tr><td>多级反馈调度</td><td>时间片轮转 + 优先级结合，多级队列不同优先级和时间片</td></tr></tbody></table><p>调度方式：<strong>可剥夺</strong>（高优先级进程可强行抢占 CPU）vs <strong>不可剥夺</strong>（必须等当前进程自动释放 CPU）。</p><h3 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h3><blockquote><p>🎯 一句话结论：死锁四条件 — 互斥、占有等待、不可剥夺、环路等待。最小资源数 = n × (R-1) + 1。</p></blockquote><p><strong>四个必要条件</strong>：资源互斥、占有并等待、不可剥夺、环路等待。⚠️ &quot;资源共享&quot;不是死锁必要条件。</p><p><strong>处理策略</strong>：</p><ul><li>死锁预防：破坏四个条件之一</li><li>死锁避免：银行家算法，提前计算安全序列，不安全则不分配</li><li>死锁检测：定时运行检测程序</li><li>死锁解除：强制剥夺资源、撤销进程</li></ul><p><strong>死锁资源计算</strong>：n 个进程各需 R 个资源，发生死锁的最大资源数 = n × (R-1)，不发生死锁的最小资源数 = n × (R-1) + 1。</p><h3 id="线程-vs-进程" tabindex="-1">线程 vs 进程 <a class="header-anchor" href="#线程-vs-进程" aria-label="Permalink to &quot;线程 vs 进程&quot;">​</a></h3><blockquote><p>🎯 一句话结论：线程是调度基本单位，进程是资源分配基本单位。同进程线程共享资源，切换开销小。</p></blockquote><p>引入线程原因：进程创建、撤销和切换时空开销大，限制了并发程度。</p><table tabindex="0"><thead><tr><th></th><th>进程</th><th>线程</th></tr></thead><tbody><tr><td>资源</td><td>独立分配资源的单位</td><td>基本不拥有资源（仅 PC、寄存器、栈）</td></tr><tr><td>调度</td><td>传统上可独立调度</td><td><strong>调度和分配的基本单位</strong></td></tr><tr><td>共享</td><td>进程间资源独立</td><td>同进程线程<strong>共享</strong>进程全部资源</td></tr><tr><td>开销</td><td>创建/切换开销大</td><td>创建/切换开销小</td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q10] 进程状态/PCB</strong></p><p>某计算机系统中的进程管理采用三态模型，那么下图所示的PCB（进程控制块）的组织方式采用（），图中（ ）。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260514222041.png" alt="image.png"></p><ul><li>A. 顺序方式</li><li>B. 链接方式</li><li>C. 索引方式</li><li>D. Hash</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：索引方式为每种进程状态建立索引表，PCB记录在索引表中。</p></div></details><hr><p><strong>[Q55] 进程状态转换</strong></p><p>下列选项中会导致进程从阻塞态变为就绪态的是（ ）。</p><ul><li>A. 进程等待的用户输入到达</li><li>B. 进程关闭文件句柄</li><li>C. 进程的时间片用完</li><li>D. 进程执行了exit()系统调用</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：阻塞→就绪：等待的事件发生（如I/O完成、用户输入到达）。</p></div></details><hr><p><strong>[Q73] 进程状态模型</strong></p><p>在操作系统中，进程状态模型包括三态模型和五态模型。关于这两种模型，以下说法正确的是（ ）。</p><ul><li>A. 三态模型包括就绪、运行和阻塞三种状态</li><li>B. 五态模型比三态模型多了挂起和终止两种状态</li><li>C. 三态模型适用于所有类型的操作系统，而五态模型仅适用于分时系统</li><li>D. 五态模型中不存在就绪状态</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：三态=就绪+运行+阻塞；五态多了挂起和终止。A和B都正确，A更基础。</p></div></details><hr><p><strong>[Q74] 进程基本状态</strong></p><p>在操作系统中，进程的基本状态不包括以下哪一种（ ）。</p><ul><li>A. 运行态</li><li>B. 就绪态</li><li>C. 阻塞态</li><li>D. 挂起态</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：挂起态是五态模型中的扩展状态，不属于基本三态。</p></div></details><hr><p><strong>[Q102] 进程组成</strong></p><p>（本题）是系统进行资源分配和调度的基本单位，通过其物理实体被操作系统所感知，物理实体分为（ ）三部分。</p><ul><li>A. 进程</li><li>B. 线程</li><li>C. 纤程</li><li>D. 管程</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：进程是资源分配和调度的基本单位。</p></div></details><hr><p><strong>[Q103] 进程组成</strong></p><p>（ ）是系统进行资源分配和调度的基本单位，通过其物理实体被操作系统所感知，物理实体分为（本题）三部分。</p><ul><li>A. 代码、文档和配置</li><li>B. 程序、数据集合和控制块</li><li>C. 进程栈、系统资源和时间片</li><li>D. 线程组、信号量和资源池</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：进程物理实体 = 程序 + 数据 + PCB（控制块）。</p></div></details><hr><p><strong>[Q104] 互斥</strong></p><p>有多个进程需要同时访问一台打印机，这时迫切需要解决（ ）问题。</p><ul><li>A. 同步</li><li>B. 互斥</li><li>C. 通信</li><li>D. 性能</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：打印机是临界资源，一次只能一个进程使用 → 互斥问题。</p></div></details><hr><p><strong>[Q46] PV操作</strong></p><p>在PV操作中，P操作的主要作用是（ ）。</p><ul><li>A. 释放资源并唤醒等待进程</li><li>B. 申请资源，若不足则阻塞进程</li><li>C. 检查资源是否可用</li><li>D. 增加信号量的值</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：P=申请（减1），不足则阻塞；V=释放（加1），有等待者则唤醒。</p></div></details><hr><p><strong>[Q70] 互斥信号量</strong></p><p>在使用信号量实现进程互斥时，以下哪个描述是正确的（ ）。</p><ul><li>A. 互斥信号量的初始值应设置为0</li><li>B. P操作会增加信号量的值</li><li>C. V操作在进入临界区之前执行</li><li>D. 互斥信号量的初始值通常设置为1</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：互斥信号量初值=1（资源可用），P在进入临界区前，V在退出后。</p></div></details><hr><p><strong>[Q71] P操作过程</strong></p><p>关于P操作（申请资源）的执行过程，以下描述正确的是（ ）。</p><ul><li>A. 将信号量S的值加1，然后判断S是否大于0</li><li>B. 将信号量S的值减1，如果S小于0则进程继续执行</li><li>C. 将信号量S的值减1，如果S大于等于0则进程继续执行</li><li>D. 将信号量S的值减1，不进行任何判断直接继续执行</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：P操作：S=S-1，若S≥0继续；若S&lt;0阻塞。</p></div></details><hr><p><strong>[Q54] 信号量值含义</strong></p><p>若信号量S的初始值为3，当前值为-1，则表示（ ）个进程正在等待该资源。</p><ul><li>A. 0</li><li>B. 1</li><li>C. 2</li><li>D. 3</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：S&lt;0时，|S|=等待进程数。|-1|=1个进程在等待。</p><p>这道题考的是 <strong>信号量值的含义</strong>，规则很简单：</p><p><strong>信号量 S 的含义：</strong></p><ul><li>S ≥ 0 → S 表示<strong>可用资源数</strong></li><li>S &lt; 0 → |S| 表示<strong>等待该资源的进程数</strong></li></ul><hr><p><strong>逐步推演：</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>S 值变化</th><th>说明</th></tr></thead><tbody><tr><td>初始</td><td>S = 3</td><td>3 个资源可用</td></tr><tr><td>进程 A 执行 P 操作</td><td>S = 2</td><td>占用 1 个，剩 2 个可用</td></tr><tr><td>进程 B 执行 P 操作</td><td>S = 1</td><td>占用 2 个，剩 1 个可用</td></tr><tr><td>进程 C 执行 P 操作</td><td>S = 0</td><td>占用 3 个，<strong>资源刚好用完</strong></td></tr><tr><td>进程 D 执行 P 操作</td><td><strong>S = -1</strong></td><td>资源已用完，<strong>D 进入等待队列</strong></td></tr></tbody></table><p>当 S = -1：</p><ul><li>绝对值 |-1| = <strong>1</strong> → 有 <strong>1 个进程</strong>在等待（进程 D）</li><li>同时意味着 3 个资源全被占用</li></ul><p><strong>所以选 B（1 个进程等待）</strong></p></div></details><hr><p><strong>[Q66] 前趋图PV规则</strong></p><p>在使用信号量实现前驱关系时，以下哪个步骤是正确的（ ）。</p><ul><li>A. 设置的信号量数量等于进程数</li><li>B. 所有信号量的初始值设为1</li><li>C. 进程执行前进行V操作，执行后进行P操作</li><li>D. 信号量数量等于有向边数量，初始值为0</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：信号量数=有向边数，初值全0，前驱执行后V，后继执行前P。</p></div></details><hr><p><strong>[Q68] 生产者-消费者</strong></p><p>在生产者-消费者问题中，以下哪个选项不属于其基本规则或约束（ ）。</p><ul><li>A. 不能向满缓冲区存产品</li><li>B. 不能向空缓冲区取产品</li><li>C. 每个时刻仅允许1个生产者或消费者存或取1个产品</li><li>D. 生产者和消费者必须同时操作缓冲区</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：不要求同时操作，但一次只有一个进程操作缓冲区。</p></div></details><hr><p><strong>[Q69] 同步目的</strong></p><p>在操作系统中，同步问题的主要目的是（ ）。</p><ul><li>A. 提高系统的运行速度</li><li>B. 确保进程间的正确协作</li><li>C. 减少内存占用</li><li>D. 增加系统的并发度</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：同步=协调速度差异，确保进程间正确协作。</p></div></details><hr><p><strong>[Q97] 并发性</strong></p><p>在单CPU环境下，操作系统的并发性是指（ ）。</p><ul><li>A. 多个程序在同一时刻同时执行</li><li>B. 宏观上多个程序同时运行，微观上时间片轮转执行</li><li>C. 多个程序必须按照严格的顺序依次执行</li><li>D. 同一时刻可以执行多个特权指令</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：单CPU并发=宏观并行、微观串行（时间片轮转）。</p></div></details><hr><p><strong>[Q64] 死锁条件</strong></p><p>在操作系统中，以下哪个条件不是产生死锁的必要条件（ ）。</p><ul><li>A. 资源共享</li><li>B. 保持和等待</li><li>C. 不可剥夺</li><li>D. 环路等待</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：死锁四条件：互斥、占有等待、不可剥夺、环路等待。&quot;资源共享&quot;不是。</p><p>死锁四个必要条件</p><table tabindex="0"><thead><tr><th>条件</th><th>含义</th></tr></thead><tbody><tr><td><strong>互斥</strong></td><td>资源一次只能给一个进程用</td></tr><tr><td><strong>保持和等待</strong></td><td>进程占着资源不放，还等别的资源</td></tr><tr><td><strong>不可剥夺</strong></td><td>资源不能被强行抢走</td></tr><tr><td><strong>环路等待</strong></td><td>进程间形成循环等待链</td></tr><tr><td>选 A 的原因</td><td></td></tr></tbody></table><p><strong>A. 资源共享</strong> ❌ — 不是必要条件</p><ul><li>死锁需要的是<strong>互斥（资源不能共享）</strong>，而不是共享</li><li>如果一个资源可以共享（比如只读文件），多个进程同时用不会死锁</li><li>所以「资源共享」恰恰是<strong>避免</strong>死锁的方向，不是产生死锁的条件</li></ul></div></details><hr><p><strong>[Q65] 死锁互斥</strong></p><p>在操作系统中，关于死锁产生的必要条件之一&quot;互斥&quot;，以下描述最准确的是（ ）。</p><ul><li>A. 互斥指多个进程可以同时访问临界资源</li><li>B. 互斥指临界资源在一段时间内只能被一个进程占用，其他进程需等待</li><li>C. 互斥指进程间不能共享任何资源</li><li>D. 互斥指进程可以随时释放已占用的资源</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：互斥=临界资源独占，一段时间内只能一个进程使用。</p></div></details><hr><p><strong>[Q47] 死锁资源计算</strong></p><p>若系统中有5个进程共享同类资源，每个进程最多需要3个资源，则系统最少需提供（ ）个资源才能避免死锁。</p><ul><li>A. 10</li><li>B. 11</li><li>C. 12</li><li>D. 15</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：最小不锁资源 = n×(R-1)+1 = 5×(3-1)+1 = 11。</p></div></details><hr><p><strong>[Q9] 并发+死锁</strong></p><p>若一个单处理器的计算机系统中同时存在3个并发进程，则同一时刻允许占用处理器的进程数（ ）；如果这3个进程都要求使用2个互斥资源R，那么系统不产生死锁的最少的R资源数为（ ）个。</p><ul><li>A. 至少为1个</li><li>B. 至少为3个</li><li>C. 最多为1个</li><li>D. 最多为3个</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C（最多1个）</p><p>解析：单处理器同一时刻最多1个进程占用CPU。死锁最小资源=3×(2-1)+1=4，选项未给出第二问。</p></div></details><hr><p><strong>[Q72] 调度</strong></p><p>在操作系统中，哪种调度不涉及进程在内存和外存之间的交换（ ）。</p><ul><li>A. 高级调度</li><li>B. 中级调度</li><li>C. 低级调度</li><li>D. 实时调度</li></ul>`,141)),s("details",u,[t[7]||(t[7]=s("summary",{class:"callout-title"},[s("span",{class:"callout-icon"},"📝"),l("答案与解析")],-1)),s("div",g,[t[3]||(t[3]=a('<p>答案：C</p><p>解析：低级调度=CPU分配，不涉及内存-外存交换；中级调度才涉及。</p><p>这道题选 <strong>C（低级调度）</strong> ✅。<code>实时调度</code> 不是三级调度中的概念，是两个不同的维度。</p><hr><p>三级调度回顾</p><table tabindex="0"><thead><tr><th>调度级别</th><th>别名</th><th>做什么</th><th style="text-align:center;">是否涉及内外存交换</th></tr></thead><tbody><tr><td><strong>高级调度</strong></td><td>作业调度</td><td>决定哪个后备作业调入内存成为就绪进程</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>中级调度</strong></td><td>对换调度</td><td>决定交换区中哪个进程换入内存</td><td style="text-align:center;">✅ 是</td></tr><tr><td><strong>低级调度</strong></td><td>进程调度</td><td>决定内存中哪个就绪进程拿到 CPU</td><td style="text-align:center;">❌ <strong>否</strong></td></tr></tbody></table><p>低级调度只看<strong>谁上 CPU</strong>，进程已经在内存里了，不涉及搬进搬出。所以选 C。</p><hr>',8)),o(n,{color:"#f79646"},{default:i(()=>[...t[1]||(t[1]=[l('实时调度不是"第四个级别"',-1)])]),_:1}),t[4]||(t[4]=a(`<p><strong>实时调度</strong>是调度<strong>算法/策略的分类</strong>，而不是一个独立的调度级别。</p><p>三级调度是按<strong>发生的位置和时机</strong>分的（作业层→交换层→CPU 层），而实时调度是按<strong>调度目标</strong>分的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调度策略分类：  </span></span>
<span class="line"><span>├── 先来先服务（FCFS）  </span></span>
<span class="line"><span>├── 时间片轮转（RR）  </span></span>
<span class="line"><span>├── 优先级调度  </span></span>
<span class="line"><span>├── 多级反馈队列  </span></span>
<span class="line"><span>└── 实时调度（保证任务在截止时间前完成）  </span></span>
<span class="line"><span>        ├── 速率单调调度（RMS）— 静态优先级  </span></span>
<span class="line"><span>        └── 最早截止时间优先（EDF）— 动态优先级</span></span></code></pre></div><p><strong>实时调度</strong>关注的是<strong>能不能按时完成</strong>，它在三级调度中属于<strong>低级调度</strong>这个层面 — 决定当前哪个进程上 CPU，只是选谁的标准变了（看截止时间而非优先级/时间片）。</p><hr>`,5)),o(n,{color:"#4bacc6"},{default:i(()=>[...t[2]||(t[2]=[l("一句话区分",-1)])]),_:1}),t[5]||(t[5]=s("p",null,[l("高级/中级/低级 = "),s("strong",null,"在哪个阶段做调度"),l(" 实时调度 = "),s("strong",null,"用什么标准来做调度"),l("（按时完成优先）")],-1)),t[6]||(t[6]=s("p",null,[l("所以题目中的 D 选项其实是一个分类错误 — 它和 A/B/C 不在同一个维度上。但标准答案还是 "),s("strong",null,"C（低级调度）"),l("，因为它是唯一明确不涉及内外存交换的")],-1))])]),t[10]||(t[10]=a(`<hr><p><strong>[Q76] 调度</strong></p><p>在操作系统中，哪种调度不存在于分时和实时操作系统中（ ）。</p><ul><li>A. 高级调度</li><li>B. 中级调度</li><li>C. 低级调度</li><li>D. 进程调度</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：高级调度（作业调度）在分时/实时OS中不存在，因为作业直接进入内存。</p></div></details><hr><blockquote><p>⭐ <strong>经典题目</strong> — PV 互斥信号量典型应用（多进程共享变量+分支中易漏 V(S)）</p></blockquote><p><strong>[Q1] PV互斥信号量</strong></p><p>某航空公司机票销售系统有n个售票点，该系统为每个售票点创建一个进程Pi(i=1，2，…，n)管理机票销售。假设Tj(j=1，2，…，m)单元存放某日某航班的机票剩余票数，Temp为Pi 进程的临时工作单元，x 为某用户的订票张数。</p><p>初始化时系统应将信号量S赋值为(请作答此空)。Pi进程的工作流程如下图所示，若用P操作和V操作实现进程间的同步与互斥，则图中空(a)、空(b)和空(c)处应分别填入(2)。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260513152010.png" alt="image.png"></p><ul><li><strong>A.</strong> 0</li><li><strong>B.</strong> 1</li><li><strong>C.</strong> 2</li><li><strong>D.</strong> 3</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：多个进程互斥访问共享变量Tj→互斥信号量初值=1。进入临界区前P(S)，退出后V(S)。</p><p>第二问：</p><p>根据典型售票流程，逻辑是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开始  </span></span>
<span class="line"><span>  ↓  </span></span>
<span class="line"><span>读用户订票数 x  </span></span>
<span class="line"><span>  ↓  </span></span>
<span class="line"><span> (a)  ______     ← 申请锁  </span></span>
<span class="line"><span>  ↓  </span></span>
<span class="line"><span>读剩余票数 Tj  </span></span>
<span class="line"><span>  ↓  </span></span>
<span class="line"><span> ┌─ x ≤ Tj ? ──→ 否 ──→ (c) ______ ──→ 结束（票不够）  </span></span>
<span class="line"><span> ↓ 是  </span></span>
<span class="line"><span> Tj = Tj - x  </span></span>
<span class="line"><span> ↓  </span></span>
<span class="line"><span>写回 Tj  </span></span>
<span class="line"><span> ↓  </span></span>
<span class="line"><span> (b)  ______     ← 释放锁  </span></span>
<span class="line"><span> ↓  </span></span>
<span class="line"><span>输出机票  </span></span>
<span class="line"><span> ↓  </span></span>
<span class="line"><span>结束</span></span></code></pre></div><p><strong>答案模式：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">空位</th><th>操作</th><th>理由</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>(a)</strong></td><td><strong>P(S)</strong></td><td>进入临界区前申请锁，防止多个进程同时操作 Tj</td></tr><tr><td style="text-align:center;"><strong>(b)</strong></td><td><strong>V(S)</strong></td><td>正常修改完 Tj 后释放锁</td></tr><tr><td style="text-align:center;"><strong>(c)</strong></td><td><strong>V(S)</strong></td><td>票不够时也要释放锁！否则其他售票点再也无法卖票（死锁）</td></tr></tbody></table><p>所以如果选项是：</p><ul><li>A. P(S)、V(S)、P(S)</li><li>B. V(S)、P(S)、V(S)</li><li>C. P(S)、V(S)、V(S)</li><li>D. V(S)、V(S)、P(S)</li></ul><p>选 <strong>C</strong> ✅ — (a)=P(S), (b)=V(S), (c)=V(S)</p><p>⚠️ <strong>(c) 容易漏</strong>：很多人在票不够的分支直接结束，忘了 V(S) 释放锁，导致整个系统死锁。</p></div></details><hr><p><strong>[Q75] 进程状态模型</strong></p><p>在操作系统中，关于进程状态模型的描述，以下哪项是正确的（ ）。</p><ul><li>A. 进程状态模型只包括三态模型</li><li>B. 进程状态模型只包括五态模型</li><li>C. 进程状态模型包括三态模型和五态模型</li><li>D. 进程状态模型不包括三态模型和五态模型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：进程状态模型包含三态(就绪/运行/阻塞)和五态(+挂起/终止)两种模型。</p></div></details>`,18))])}const _=p(c,[["render",h]]);export{v as __pageData,_ as default};
